// WildDex entries, grouped into album "sheets".
//
// Each entry maps to one or more ImageNet class indices (`c`) - the scanner
// sums the model's probability over those classes, so e.g. every dog breed
// counts toward "Dog" and is remembered as a separate form.
//
// Keys: k key, n name, s scientific name, e emoji (silhouette for locked
// stamps), r rarity (1 common .. 4 legendary), c classes, h habitat,
// d diet, z size, t dex entry text, f fun fact.

const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

