// Flat, numbered list (#001, #002 ...) in album order.
export const ENTRIES = [];
for (const set of SETS) {
  for (const e of set.entries) {
    e.no = ENTRIES.length + 1;
    e.set = set.id;
    ENTRIES.push(e);
  }
}
export const BY_KEY = Object.fromEntries(ENTRIES.map((e) => [e.k, e]));

// ImageNet classes 0-397 are animals (plus two fossils); 398+ are objects.
export const ANIMAL_CLASS_LIMIT = 398;
